/**
 * Shared table / column / status literals used by send-path I/O shells.
 * Kept here so StringLiteral mutants are killed by direct constant tests
 * instead of surviving inside thick supabase call chains.
 *
 * ignoreStatic: module-level const initializers are not mutated; I/O files
 * reference these instead of inline 'id' / 'status' / filter fragments.
 */

export const TABLE = {
  leads: 'leads',
  businesses: 'businesses',
  smsMessages: 'sms_messages',
  missedCalls: 'missed_calls',
  campaigns: 'campaigns',
  campaignSteps: 'campaign_steps',
  campaignEnrollments: 'campaign_enrollments',
} as const;

/** PostgREST / SQL column names used in .eq / .order / .select. */
export const COL = {
  id: 'id',
  leadId: 'lead_id',
  messageSid: 'message_sid',
  status: 'status',
  body: 'body',
  nextRetryAt: 'next_retry_at',
  nextSendAt: 'next_send_at',
  claimToken: 'claim_token',
  claimedAt: 'claimed_at',
  campaignId: 'campaign_id',
  stepNumber: 'step_number',
  autoEnroll: 'auto_enroll',
  sentAt: 'sent_at',
  smsOutboundSid: 'sms_outbound_sid',
  optedOut: 'opted_out',
  phone: 'phone',
  businessId: 'business_id',
  callerPhone: 'caller_phone',
  createdAt: 'created_at',
  direction: 'direction',
  callSid: 'call_sid',
  ringDuration: 'ring_duration',
  missedCallId: 'missed_call_id',
  urgency: 'urgency',
  issue: 'issue',
  smsResponseText: 'sms_response_text',
  classifiedAt: 'classified_at',
  updatedAt: 'updated_at',
  needsHumanReview: 'needs_human_review',
  needsHumanReviewAt: 'needs_human_review_at',
  needsHumanReviewReason: 'needs_human_review_reason',
  optedOutAt: 'opted_out_at',
} as const;

export const DIRECTION_INBOUND = 'inbound';

export const LEAD_STATUS = {
  pending: 'pending',
  qualified: 'qualified',
  escalated: 'escalated',
  spam: 'spam',
} as const;

export const OPEN_LEAD_STATUSES = [
  LEAD_STATUS.qualified,
  LEAD_STATUS.escalated,
] as const;

export const LEGACY_LEAD_STATUSES = [
  LEAD_STATUS.pending,
  LEAD_STATUS.qualified,
  LEAD_STATUS.escalated,
] as const;

export const INBOUND_MESSAGE_ID_PREFIX = 'brwn-in-';

export const ENV_BRWN_DEFAULT_BUSINESS_PHONE = 'BRWN_DEFAULT_BUSINESS_PHONE';

export const SMS_STATUS = {
  sending: 'sending',
  deferred: 'deferred',
  unknown: 'unknown',
  needsReview: 'needs_review',
  abandonedRetry: 'abandoned_retry',
  abandonedDone: 'abandoned_done',
  queued: 'queued',
  dispatched: 'dispatched',
  sent: 'sent',
  delivered: 'delivered',
  active: 'active',
  paused: 'paused',
  completed: 'completed',
  received: 'received',
} as const;

export const ENROLLMENT_STATUS = {
  active: 'active',
  paused: 'paused',
  completed: 'completed',
  needsReview: 'needs_review',
} as const;

export const DIRECTION_OUTBOUND = 'outbound';

export const LEAD_SELECT_GATES = 'opted_out, timezone, sms_outbound_sid';
export const LEAD_SELECT_STAR = '*';

export const ORDER_CREATED_DESC = { ascending: false } as const;
export const SMS_SELECT_STATUS = 'status';
export const SMS_SELECT_ID_STATUS = 'id, status';
export const SMS_SELECT_DEFERRED =
  'id, lead_id, message_sid, body, next_retry_at, reconcile_attempts';

/** Cap for never_sent / unexpected ignore-path retries on deferred drain. */
export const DEFERRED_IGNORE_MAX_ATTEMPTS = 5;
export const SMS_SELECT_RECONCILE =
  'id, lead_id, message_sid, status, sent_at, reconcile_attempts, key_supported_at_send, next_retry_at';
export const SMS_SELECT_ABANDONED = 'id, lead_id, message_sid, status';
export const SMS_SELECT_CONFIRMED = 'message_sid, status';
export const LEAD_SELECT_STAR_BIZ = '*, businesses(*)';
export const LEAD_SELECT_OPTED_OUT = 'opted_out';
export const LEAD_SELECT_OUTBOUND = 'sms_outbound_sid';
export const ENROLLMENT_SELECT_STAR = '*';
export const ENROLLMENT_SELECT_ID = 'id';
export const CAMPAIGN_SELECT_STAR_STEPS = '*, campaign_steps(*)';
export const CAMPAIGN_SELECT_URGENCY = 'id, name, urgency_filter';
export const STEP_SELECT_STAR = '*';
export const ENROLLMENT_SELECT_SEND =
  '*, leads!inner(*, businesses(*)), campaigns!inner(*)';
export const ENROLLMENT_SELECT_ADVANCE =
  'id, campaign_id, current_step, status, claim_token';
export const ENROLLMENT_SELECT_REQUEUE = 'id, campaign_id, status';

export const PG_UNIQUE = '23505';

/** Statuses considered confirmed delivery for post-reconcile advance. */
export const CONFIRMED_PROVIDER_STATUSES = [
  SMS_STATUS.queued,
  SMS_STATUS.dispatched,
  SMS_STATUS.sent,
  SMS_STATUS.delivered,
] as const;

/** Reconcile cron pulls unknown + stuck sending. */
export const RECONCILE_PULL_STATUSES = [
  SMS_STATUS.unknown,
  SMS_STATUS.sending,
] as const;

export const CAMPAIGN_SID_LIKE = 'mlf:campaign:%';

export const ABANDONED_SID_RE = /:abandoned:\d+$/;

export const REVIEW_REASON_QUIET_HOURS = 'quiet_hours_unresolved';

export const KIND_RECOVERY = 'recovery';
export const KIND_CAMPAIGN = 'campaign';
export const KIND_MANUAL = 'manual';

export const SEND_REASON = {
  invalidPhone: 'invalid_phone',
  duplicateInFlight: 'duplicate_in_flight',
  lookupUnsupported: 'lookup_unsupported',
  sendsDisabled: 'sends_disabled',
} as const;

export const RELAY_SIGNAL = {
  error: 'error',
  unknown: 'unknown',
  ok: 'ok',
} as const;

export const LOOKUP_KIND = 'lookup';

export function reconcileOrFilter(nowIso: string, cutoff: string): string {
  return (
    `and(status.eq.unknown,next_retry_at.is.null),` +
    `and(status.eq.unknown,next_retry_at.lte.${nowIso}),` +
    `and(status.eq.sending,sent_at.lt.${cutoff})`
  );
}

src/services/inbound.ts.source:
import {
  inboundAmbiguousReviewPayload,
  inboundQualifiedLeadPayload,
  inboundSmsInsertInput,
  inboundSmsReceivedPayload,
  stopLeadLookupResult,
} from '@/services/inbound-io-plans';
import { LEAD_LOOKUP_MAX_AGE_DAYS } from '@/services/campaign-logic';
import {
  COL,
  ENV_BRWN_DEFAULT_BUSINESS_PHONE,
  INBOUND_MESSAGE_ID_PREFIX,
  LEAD_SELECT_STAR,
  LEAD_STATUS,
  LEGACY_LEAD_STATUSES,
  OPEN_LEAD_STATUSES,
  ORDER_CREATED_DESC,
  TABLE,
} from '@/services/db-strings';
import type { Database } from '@/types/database';
import {
  defaultInboundDeps,
  type InboundDeps,
} from '@/services/inbound-deps';

type Lead = Database['public']['Tables']['leads']['Row'];

const OPT_OUT_SUPPRESS_REASON = 'opt_out';
const INBOUND_BODY_MAX_LEN = 1600;

export interface InboundSmsEvent {
  from: string;
  body: string;
  businessPhone: string;
  messageId?: string;
}

export type InboundResult =
  | {
      status: 'processed';
      leadId: string;
      urgency: string;
      enrollmentAction?: string;
      enrolledCampaign?: string;
    }
  | { status: 'opt_out_recorded'; leadId?: string }
  | { status: 'ambiguous_opt_out'; leadId?: string }
  | { status: 'no_lead_found' };

export type { InboundDeps };
export { defaultInboundDeps };

export async function processInboundSms(
  event: InboundSmsEvent
): Promise<InboundResult> {
  return processInboundSmsWithDeps(defaultInboundDeps(), event);
}

export async function processInboundSmsWithDeps(
  deps: InboundDeps,
  event: InboundSmsEvent
): Promise<InboundResult> {
  const supabase = deps.db();
  const body = event.body.slice(0, INBOUND_BODY_MAX_LEN);
  const messageId =
    event.messageId ||
    `${INBOUND_MESSAGE_ID_PREFIX}${deps.clock().getTime()}-${deps.randomSuffix()}`;

  const { data: business, error: bizError } = await supabase
    .from(TABLE.businesses)
    .select(LEAD_SELECT_STAR)
    .eq(COL.phone, event.businessPhone)
    .single();

  if (bizError || !business) {
    // Stryker disable StringLiteral,CallExpression: log-only (no control flow)
    console.error(
      'Business not found for number:',
      deps.redactPhone(event.businessPhone)
    );
    // Stryker restore StringLiteral,CallExpression
    throw new InboundError('Business not found', 404);
  }

  const fromE164 = deps.tryNormalizeToE164(event.from);
  const phoneForLookup = fromE164 || event.from.trim();

  const optOutVerdict = deps.classifyOptOut(body);

  if (optOutVerdict.kind === 'opt_out' || deps.isOptOutMessage(body)) {
    if (!fromE164) {
      // Stryker disable StringLiteral,CallExpression,BlockStatement: log-only (no control flow)
      console.warn(
        'Definite STOP from non-normalizable sender; recording without E.164 suppress',
        deps.redactPhone(event.from)
      );
      // Stryker restore StringLiteral,CallExpression,BlockStatement
    }

    const { data: anyLead } = await supabase
      .from(TABLE.leads)
      .select(COL.id)
      .eq(COL.businessId, business.id)
      .eq(COL.callerPhone, phoneForLookup)
      .order(COL.createdAt, ORDER_CREATED_DESC)
      .limit(1)
      .maybeSingle();

    const skipSecondLookup =
      anyLead != null || phoneForLookup === event.from;
    const shortCircuit = stopLeadLookupResult(anyLead, skipSecondLookup);
    const { data: rawLead } =
      shortCircuit === null
        ? await supabase
            .from(TABLE.leads)
            .select(COL.id)
            .eq(COL.businessId, business.id)
            .eq(COL.callerPhone, event.from)
            .order(COL.createdAt, ORDER_CREATED_DESC)
            .limit(1)
            .maybeSingle()
        : shortCircuit;

    const leadId = anyLead?.id || rawLead?.id;

    if (fromE164) {
      await deps.suppressPhoneForBusiness(
        business.id,
        fromE164,
        OPT_OUT_SUPPRESS_REASON
      );
    }

    if (leadId) {
      await deps.markLeadOptedOut(leadId).catch((err) => {
        // Stryker disable StringLiteral,CallExpression,BlockStatement: log-only (no control flow)
        console.error(
          'Failed to mark lead opted out:',
          err instanceof Error ? err.message : 'unknown'
        );
        // Stryker restore StringLiteral,CallExpression,BlockStatement
      });
      await deps.pauseCampaignForLead(leadId).catch(() => undefined);
      await supabase.from(TABLE.smsMessages).insert(
        inboundSmsReceivedPayload(
          inboundSmsInsertInput({
            leadId,
            body,
            messageSid: messageId,
          })
        )
      );
      return {
        status: 'opt_out_recorded',
        leadId,
      };
    }

    return { status: 'opt_out_recorded' };
  }

  if (optOutVerdict.kind === 'ambiguous') {
    // Stryker disable StringLiteral,CallExpression: log-only (no control flow)
    console.warn(
      `Ambiguous opt-out language from ${deps.redactPhone(event.from)}: needs_human_review`
    );
    // Stryker restore StringLiteral,CallExpression
    const { data: anyLead } = await supabase
      .from(TABLE.leads)
      .select(COL.id)
      .eq(COL.businessId, business.id)
      .eq(COL.callerPhone, phoneForLookup)
      .order(COL.createdAt, ORDER_CREATED_DESC)
      .limit(1)
      .maybeSingle();

    if (anyLead?.id) {
      await supabase
        .from(TABLE.leads)
        .update(
          inboundAmbiguousReviewPayload({
            reason: optOutVerdict.reason,
            flaggedAt: deps.clock().toISOString(),
          })
        )
        .eq(COL.id, anyLead.id);
      await supabase.from(TABLE.smsMessages).insert(
        inboundSmsReceivedPayload(
          inboundSmsInsertInput({
            leadId: anyLead.id,
            body,
            messageSid: messageId,
          })
        )
      );
      return { status: 'ambiguous_opt_out', leadId: anyLead.id };
    }
    return { status: 'ambiguous_opt_out' };
  }

  if (!fromE164) {
    // Stryker disable StringLiteral,CallExpression: log-only (no control flow)
    console.error('Invalid sender phone for inbound:', deps.redactPhone(event.from));
    // Stryker restore StringLiteral,CallExpression
    return { status: 'no_lead_found' };
  }

  const cutoff = new Date(
    deps.clock().getTime() - LEAD_LOOKUP_MAX_AGE_DAYS * 24 * 60 * 60 * 1000
  ).toISOString();

  const { data: pendingLead } = await supabase
    .from(TABLE.leads)
    .select(LEAD_SELECT_STAR)
    .eq(COL.businessId, business.id)
    .eq(COL.callerPhone, fromE164)
    .eq(COL.status, LEAD_STATUS.pending)
    .gte(COL.createdAt, cutoff)
    .order(COL.createdAt, { ascending: false })
    .limit(1)
    .maybeSingle();

  let lead: Lead | null = pendingLead;

  if (!lead) {
    const { data: openLead } = await supabase
      .from(TABLE.leads)
      .select(LEAD_SELECT_STAR)
      .eq(COL.businessId, business.id)
      .eq(COL.callerPhone, fromE164)
      .in(COL.status, OPEN_LEAD_STATUSES as unknown as string[])
      .gte(COL.createdAt, cutoff)
      .order(COL.createdAt, ORDER_CREATED_DESC)
      .limit(1)
      .maybeSingle();
    lead = openLead;
  }

  if (!lead && fromE164 !== event.from) {
    const { data: legacy } = await supabase
      .from(TABLE.leads)
      .select(LEAD_SELECT_STAR)
      .eq(COL.businessId, business.id)
      .eq(COL.callerPhone, event.from)
      .in(COL.status, LEGACY_LEAD_STATUSES as unknown as string[])
      .gte(COL.createdAt, cutoff)
      .order(COL.createdAt, ORDER_CREATED_DESC)
      .limit(1)
      .maybeSingle();
    lead = legacy;
  }

  if (!lead || !deps.isLeadWithinLookupAge(lead.created_at, deps.clock())) {
    // Stryker disable StringLiteral,CallExpression: log-only (no control flow)
    console.error('No recent open lead found for:', deps.redactPhone(event.from));
    // Stryker restore StringLiteral,CallExpression
    return { status: 'no_lead_found' };
  }

  await supabase.from(TABLE.smsMessages).insert(
    inboundSmsReceivedPayload(
      inboundSmsInsertInput({
        leadId: lead.id,
        body,
        messageSid: messageId,
      })
    )
  );

  const classification = await deps.classifyUrgency(body, business.vertical);

  const { error: updateError } = await supabase
    .from(TABLE.leads)
    .update(
      inboundQualifiedLeadPayload({
        urgency: classification.urgency,
        issue: classification.issue ?? null,
        body,
        classifiedAt: deps.clock().toISOString(),
      })
    )
    .eq(COL.id, lead.id);

  // Stryker disable next-line ConditionalExpression: log-only — update failure only logs
  if (updateError) {
    // Stryker disable StringLiteral,CallExpression: log-only (no control flow)
    console.error('Failed to update lead:', updateError.message);
    // Stryker restore StringLiteral,CallExpression
  }

  const enrollment = await deps
    .handleClassifiedReplyEnrollment(lead.id, classification.urgency)
    .catch((err) => {
      // Stryker disable StringLiteral,CallExpression,BlockStatement: log-only (no control flow)
      console.error(
        'Enrollment handling failed:',
        err instanceof Error ? err.message : 'unknown'
      );
      // Stryker restore StringLiteral,CallExpression,BlockStatement
      return { action: 'error', campaignName: undefined as string | undefined };
    });

  if (
    classification.urgency === 'emergency' ||
    classification.urgency === 'high'
  ) {
    await deps.escalateLead(lead.id, business, classification);
  }

  return {
    status: 'processed',
    leadId: lead.id,
    urgency: classification.urgency,
    enrollmentAction: enrollment.action,
    enrolledCampaign: enrollment.campaignName,
  };
}

export function resolveBusinessPhone(
  payloadTo: string | undefined | null
): string | null {
  const fromPayload = payloadTo?.trim();
  if (fromPayload) return fromPayload;
  const fromEnv = process.env[ENV_BRWN_DEFAULT_BUSINESS_PHONE]?.trim();
  return fromEnv || null;
}

export class InboundError extends Error {
  constructor(
    message: string,
    readonly status: number
  ) {
    super(message);
    this.name = 'InboundError';
  }
}

