/**
 * TCPA / carrier opt-out detection (QC r7 first-principles rewrite).
 *
 * 1. Normalize (NFKC, confusables, zero-width, punctuation trim, upper).
 * 2. Whole message equals a carrier keyword → opt_out (auto-suppress).
 * 3. Keyword as a whole word inside a longer message → ambiguous (flag only).
 * 4. Never substring / compact-includes matching.
 *
 * Shared token list: opt-out-data.ts (also used by migration 003 backfill).
 */

import {
  CONFUSABLES,
  OPT_OUT_COMPACT,
  OPT_OUT_EXACT,
  OPT_OUT_MULTIWORD_STEMS,
  OPT_OUT_WHOLE_MESSAGE,
  OPT_OUT_WHOLE_MESSAGE_COMPACT,
  OPT_OUT_WORD_STEMS,
  optOutBackfillCompactList,
  optOutBackfillExactList,
} from './opt-out-data';

export type OptOutVerdict =
  | { kind: 'opt_out' }
  | { kind: 'ambiguous'; reason: string }
  | { kind: 'not_opt_out' };

export {
  OPT_OUT_EXACT,
  OPT_OUT_COMPACT,
  OPT_OUT_WHOLE_MESSAGE,
  OPT_OUT_WHOLE_MESSAGE_COMPACT,
  OPT_OUT_WORD_STEMS,
  OPT_OUT_MULTIWORD_STEMS,
};

const ZERO_WIDTH_RE =
  /[\u200B-\u200D\uFEFF\u2060\u180E\u00AD\u034F\u061C\u115F\u1160\u17B4\u17B5\u3164\uFFA0]/g;

const QUOTE_EDGE_RE = /^["'`“”‘’]+|["'`“”‘’]+$/g;

const WHOLE_MESSAGE_SET = new Set<string>(OPT_OUT_WHOLE_MESSAGE);
const WHOLE_COMPACT_SET = new Set<string>(OPT_OUT_WHOLE_MESSAGE_COMPACT);

/** Replace NBSP with a real space so token boundaries survive collapse. */
export function replaceNbspWithSpace(s: string): string {
  return s.replace(/\u00a0/g, ' ');
}

/** Strip leading/trailing straight + smart quotes (both anchors required). */
export function stripEdgeQuotes(s: string): string {
  return s.replace(QUOTE_EDGE_RE, '');
}

export function foldConfusables(raw: string): string {
  let out = '';
  for (const ch of raw) {
    out += CONFUSABLES[ch] ?? ch;
  }
  return out;
}

/**
 * Canonical normalizer used by inbound webhook AND migration 003 backfill.
 */
export function normalizeOptOutText(raw: string): string {
  const folded = foldConfusables(raw)
    .normalize('NFKC')
    .replace(ZERO_WIDTH_RE, '')
    .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, '');
  const spaced = replaceNbspWithSpace(folded);
  // Stryker disable next-line Regex,MethodExpression: later /\s+/g + final trim make newline/+ and mid-trim equivalent
  const lined = spaced.replace(/[\r\n]+/g, ' ').trim();
  // Strip edge quotes, then trailing punct, then quotes again so e.g. `#"!` → `#`
  // (punct uncovering a quote) stays idempotent.
  const once = stripEdgeQuotes(lined)
    .replace(/[\s?!.,…]+$/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  return stripEdgeQuotes(once).trim().toUpperCase();
}

/** Spaceless form so 'S T O P' compact to STOP. */
export function compactOptOutText(normalized: string): string {
  return normalized.replace(/[^A-Z0-9]/g, '');
}

/** True when `stem` appears as a whole word/token in normalized text. */
export function hasWholeWordStem(normalized: string, stem: string): boolean {
  if (stem.includes(' ') || stem.includes('-')) {
    const escaped = stem.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return new RegExp(`(?:^|[^A-Z0-9])${escaped}(?:[^A-Z0-9]|$)`).test(
      normalized
    );
  }
  return new RegExp(`(?:^|[^A-Z0-9])${stem}(?:[^A-Z0-9]|$)`).test(normalized);
}

/**
 * Classify an inbound body for opt-out.
 * Whole-message keyword → opt_out; keyword inside longer text → ambiguous.
 */
export function classifyOptOut(raw: string): OptOutVerdict {
  const normalized = normalizeOptOutText(raw);
  // Stryker disable next-line ConditionalExpression: empty never matches whole-message/stem sets
  if (!normalized) return { kind: 'not_opt_out' };

  const compact = compactOptOutText(normalized);

  // Collapse spaced single letters ("S T O P PLEASE" → "STOP PLEASE") then
  // re-check whole-message sets — still whole-message, never substring.
  const collapsed = collapseSpacedLetterTokens(normalized);
  const collapsedCompact = compactOptOutText(collapsed);

  if (
    WHOLE_MESSAGE_SET.has(normalized) ||
    WHOLE_COMPACT_SET.has(compact) ||
    WHOLE_MESSAGE_SET.has(collapsed) ||
    WHOLE_COMPACT_SET.has(collapsedCompact)
  ) {
    return { kind: 'opt_out' };
  }

  // Keyword as a whole word inside a longer message → human review only
  for (const stem of OPT_OUT_WORD_STEMS) {
    if (
      hasWholeWordStem(normalized, stem) ||
      hasWholeWordStem(collapsed, stem)
    ) {
      return { kind: 'ambiguous', reason: 'keyword_in_sentence' };
    }
  }
  for (const stem of OPT_OUT_MULTIWORD_STEMS) {
    if (
      hasWholeWordStem(normalized, stem) ||
      hasWholeWordStem(collapsed, stem)
    ) {
      return { kind: 'ambiguous', reason: 'keyword_in_sentence' };
    }
  }

  return { kind: 'not_opt_out' };
}

/** Join runs of single-letter tokens: "S T O P PLEASE" → "STOP PLEASE". */
export function collapseSpacedLetterTokens(normalized: string): string {
  return normalized.replace(/\b(?:[A-Z]\s+){1,}[A-Z]\b/g, (m) =>
    // Stryker disable next-line Regex: /\s/g vs /\s+/g identical for space runs here
    m.replace(/\s+/g, '')
  );
}

/** True only for definite auto opt-out. */
export function isDefiniteOptOut(raw: string): boolean {
  return classifyOptOut(raw).kind === 'opt_out';
}

/**
 * Tokens for migration 003 STOP backfill — whole-message only (no mid-sentence).
 */
export function optOutBackfillTokens(): string[] {
  const set = new Set<string>([
    ...optOutBackfillExactList(),
    ...optOutBackfillCompactList(),
  ]);
  return [...set];
}

/**
 * Pure predicate mirroring migration 003 whole-message backfill.
 * Used by the parity test so app + SQL share one corpus.
 */
export function wouldBackfillSuppress(raw: string): boolean {
  const normalized = normalizeOptOutText(raw);
  // Stryker disable next-line ConditionalExpression: empty never hits whole-message sets
  if (!normalized) return false;
  const compact = compactOptOutText(normalized);
  const collapsed = collapseSpacedLetterTokens(normalized);
  const collapsedCompact = compactOptOutText(collapsed);
  return (
    WHOLE_MESSAGE_SET.has(normalized) ||
    WHOLE_COMPACT_SET.has(compact) ||
    WHOLE_MESSAGE_SET.has(collapsed) ||
    WHOLE_COMPACT_SET.has(collapsedCompact)
  );
}

export const OPT_OUT_FOOTER = 'Reply STOP to opt out.';

src/services/send/machine.ts.source:
/**
 * Pure send/reconcile state machine.
 *
 * Lifecycle:
 *   queued → sent | never_sent | ambiguous → (reconcile) → resolved | needs_review
 *
 * Transitions are total and deterministic — property-tested with fast-check.
 */

export const MAX_RECONCILE_ATTEMPTS = 5;

/** Base park interval (5 min); doubles each attempt, capped at 6h. */
export const PARK_BASE_MS = 5 * 60 * 1000;
export const PARK_MAX_MS = 6 * 60 * 60 * 1000;

export type RelaySendSignal =
  | { type: 'ok'; messageId: string; status: string; keyEchoed: boolean; duplicate?: boolean }
  | { type: 'conflict' }
  | { type: 'rate_limit' }
  | { type: 'maintenance' }
  | { type: 'failed'; status?: string }
  | { type: 'error' };

export type RelayLookupSignal =
  | { type: 'sent'; status: string }
  | { type: 'never_sent' }
  | { type: 'failed'; status: string }
  | { type: 'unknown' };

export type SendRowPhase =
  | 'queued'
  | 'sending'
  | 'sent'
  | 'never_sent'
  | 'ambiguous'
  | 'needs_review'
  | 'resolved';

export type SendMachineEvent =
  | { kind: 'send_result'; signal: RelaySendSignal; capsBeforeSend: boolean }
  | { kind: 'lookup'; signal: RelayLookupSignal; keySupportedAtSend: boolean; attempts: number };

export type SendMachineDecision =
  | {
      action: 'confirm_sent';
      providerStatus: string;
      keySupportedAtSend: boolean;
      phase: 'sent';
    }
  | { action: 'park_ambiguous'; reason: string; phase: 'ambiguous'; nextAttempts: number }
  | { action: 'needs_review'; reason: string; phase: 'needs_review' }
  | { action: 'requeue_never_sent'; phase: 'never_sent' }
  | { action: 'resolved'; providerStatus: string; phase: 'resolved' };

export function parkDelayMs(reconcileAttempts: number): number {
  const n = Number(reconcileAttempts);
  // n > 0 (not >=): Math.floor(0) === 0 so >= is equivalent for the exp path;
  // still require finite + positive so NaN/Infinity/negatives park at base delay.
  // Stryker disable next-line EqualityOperator: n >= 0 ≡ n > 0 here (floor(0)===0)
  const exp = Number.isFinite(n) && n > 0 ? Math.floor(n) : 0;
  const raw = PARK_BASE_MS * 2 ** exp;
  return Math.min(raw, PARK_MAX_MS);
}

export function parkNextAt(
  reconcileAttempts: number,
  now: Date = new Date()
): Date {
  return new Date(now.getTime() + parkDelayMs(reconcileAttempts));
}

const FAILED_STATUSES = new Set([
  'failed',
  'undelivered',
  'rejected',
  'error',
]);

const CONFIRMED_STATUSES = new Set([
  'queued',
  'dispatched',
  'sent',
  'delivered',
]);

/**
 * Apply a send or lookup event to the row state machine.
 * Does not perform I/O — callers persist the decision.
 */
export function transitionSend(event: SendMachineEvent): SendMachineDecision {
  if (event.kind === 'send_result') {
    return onSendResult(event.signal, event.capsBeforeSend);
  }
  return onLookup(
    event.signal,
    event.keySupportedAtSend,
    event.attempts
  );
}

function onSendResult(
  signal: RelaySendSignal,
  capsBeforeSend: boolean
): SendMachineDecision {
  switch (signal.type) {
    case 'ok': {
      if (signal.duplicate && isFailedStatus(signal.status)) {
        return { action: 'needs_review', reason: 'duplicate_failed', phase: 'needs_review' };
      }
      if (isFailedStatus(signal.status)) {
        return { action: 'needs_review', reason: 'relay_failed', phase: 'needs_review' };
      }
      return {
        action: 'confirm_sent',
        providerStatus: signal.status || 'queued',
        keySupportedAtSend: capsBeforeSend && signal.keyEchoed,
        phase: 'sent',
      };
    }
    case 'conflict':
      return { action: 'needs_review', reason: 'idempotency_conflict', phase: 'needs_review' };
    case 'failed':
      return { action: 'needs_review', reason: 'relay_failed', phase: 'needs_review' };
    case 'rate_limit':
      return {
        action: 'park_ambiguous',
        reason: 'recent_send',
        phase: 'ambiguous',
        nextAttempts: 0,
      };
    case 'maintenance':
      return {
        action: 'park_ambiguous',
        reason: 'maintenance',
        phase: 'ambiguous',
        nextAttempts: 0,
      };
    // Stryker disable next-line StringLiteral,ConditionalExpression: case 'error' ≡ default body
    case 'error':
    default:
      return {
        action: 'park_ambiguous',
        reason: 'send_error',
        phase: 'ambiguous',
        nextAttempts: 0,
      };
  }
}

function onLookup(
  signal: RelayLookupSignal,
  keySupportedAtSend: boolean,
  attempts: number
): SendMachineDecision {
  switch (signal.type) {
    case 'sent':
      if (isFailedStatus(signal.status)) {
        return { action: 'needs_review', reason: 'relay_status_failed', phase: 'needs_review' };
      }
      // Non-terminal / odd statuses on found:true → park (never invent resolved)
      if (!isConfirmedStatus(signal.status)) {
        const next = attempts + 1;
        if (next >= MAX_RECONCILE_ATTEMPTS) {
          return { action: 'needs_review', reason: 'max_attempts', phase: 'needs_review' };
        }
        return {
          action: 'park_ambiguous',
          reason: 'lookup_nonterminal',
          phase: 'ambiguous',
          nextAttempts: next,
        };
      }
      // status is non-empty here: falsy values fail isConfirmedStatus above
      return {
        action: 'resolved',
        providerStatus: signal.status,
        phase: 'resolved',
      };
    case 'failed':
      return { action: 'needs_review', reason: 'relay_status_failed', phase: 'needs_review' };
    case 'never_sent':
      if (!keySupportedAtSend) {
        return {
          action: 'needs_review',
          reason: 'never_sent_without_key_support',
          phase: 'needs_review',
        };
      }
      return { action: 'requeue_never_sent', phase: 'never_sent' };
    // Stryker disable next-line StringLiteral,ConditionalExpression -- case 'unknown' ≡ default body
    case 'unknown':
    default: {
      const next = Math.max(0, attempts) + 1;
      if (next >= MAX_RECONCILE_ATTEMPTS) {
        return { action: 'needs_review', reason: 'max_attempts', phase: 'needs_review' };
      }
      return {
        action: 'park_ambiguous',
        reason: 'lookup_unknown',
        phase: 'ambiguous',
        nextAttempts: next,
      };
    }
  }
}

export function isFailedStatus(status: string | null | undefined): boolean {
  // Stryker disable next-line StringLiteral -- ?? '' vs filler both miss FAILED_STATUSES
  return FAILED_STATUSES.has(String(status ?? '').toLowerCase());
}

export function isConfirmedStatus(status: string | null | undefined): boolean {
  // Stryker disable next-line StringLiteral -- ?? '' vs filler both miss CONFIRMED_STATUSES
  return CONFIRMED_STATUSES.has(String(status ?? '').toLowerCase());
}

export function isAmbiguousStatus(status: string | null | undefined): boolean {
  // Stryker disable next-line StringLiteral -- ?? '' vs filler both miss ambiguous tokens
  const s = String(status ?? '').toLowerCase();
  return s === 'sending' || s === 'unknown' || s === 'deferred' || s === 'pending';
}

/** Recovery resolution used to gate campaign step 1. */
export type RecoveryResolvedOutcome =
  | 'resolved_sent'
  | 'resolved_abandoned'
  | 'pending'
  | 'absent';

export function classifyRecoveryStatus(
  status: string | null | undefined
): RecoveryResolvedOutcome {
  if (!status) return 'absent';
  const s = String(status).toLowerCase();
  if (isConfirmedStatus(s)) return 'resolved_sent';
  if (s === 'abandoned_retry' || s === 'abandoned_done') return 'resolved_abandoned';
  // Ambiguous / failed / needs_review / deferred / unknown vocabulary → pending
  // (never treat as absent → no step-1 double send). Prior explicit pending
  // branches were equivalent to this fallthrough and only fed survivor mutants.
  return 'pending';
}

