  it('blocks invalid phone', async () => {
    const deps = baseDeps({});
    const o = await sendMessageWithDeps(deps, {
      kind: 'recovery',
      leadId: 'L',
      businessId: 'B',
      to: 'not-a-phone',
      body: 'hi',
    });
